#include "backend.h"
#include "third_party/json.hpp"
#include <set>
namespace ldcontrol {
using Json=nlohmann::json;
static std::wstring configPath(){wchar_t buf[32768];DWORD n=GetModuleFileNameW(nullptr,buf,32768);if(!n||n==32768)return {};std::wstring p(buf,n);return p.substr(0,p.find_last_of(L"\\/")+1)+L"LDMenu.json";}
static std::string utf8(const std::wstring& s){if(s.empty())return {};int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),int(s.size()),nullptr,0,nullptr,nullptr);if(!n)return {};std::string out(n,'\0');WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),int(s.size()),out.data(),n,nullptr,nullptr);return out;}
static std::wstring fromUtf8(const std::string&s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),nullptr,0);if(!n)return {};std::wstring out(n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),out.data(),n);return out;}
bool validConfig(const Config&c){return (c.function==0||c.function==2||c.function==13)&&c.filter>=0&&c.filter<=6;}
bool validGlobal(const GlobalSettings&g){if(!validConfig(g.defaults)||g.settleSeconds>600||g.playDelaySeconds>3600||g.playTargets.size()>512)return false;std::set<int> seen;for(const auto&t:g.playTargets)if(t.index<0||t.index>30000||t.name.empty()||t.name.size()>256||!seen.insert(t.index).second)return false;return true;}
static Json configJson(const Config&c){return {{"functionIndex",c.function},{"filterIndex",c.filter},{"sell",c.sell},{"reconnect",c.reconnect}};}
bool decodeSettings(const std::string& text,std::vector<SavedConfig>&out,GlobalSettings*global){try{
    if(text.size()>262144)return false;auto j=Json::parse(text);if(!j.is_object()||!j.contains("schema")||j["schema"]!=1||!j.contains("devices")||!j["devices"].is_array()||j["devices"].size()>512)return false;
    std::vector<SavedConfig> parsed;std::set<int> seen;
    auto integer=[](const Json&v,int low,int high,int&dest){if(!v.is_number_integer())return false;if(v.is_number_unsigned()){auto n=v.get<unsigned long long>();if(n>static_cast<unsigned>(high))return false;dest=int(n);}else{auto n=v.get<long long>();if(n<low||n>high)return false;dest=int(n);}return dest>=low;};
    GlobalSettings common;
    if(j.contains("global")){const auto&g=j.at("global");const auto&d=g.at("defaults");int seconds=0;if(!g.is_object()||!d.is_object()||!integer(g.at("postConnectDelaySeconds"),0,600,seconds)||!integer(d.at("functionIndex"),0,13,common.defaults.function)||!integer(d.at("filterIndex"),0,6,common.defaults.filter)||!d.at("sell").is_boolean()||!d.at("reconnect").is_boolean())return false;common.settleSeconds=unsigned(seconds);common.defaults.sell=d["sell"];common.defaults.reconnect=d["reconnect"];if(!validGlobal(common))return false;}
    if(j.contains("global")){const auto&g=j.at("global");if(g.contains("playDelaySeconds")){int seconds=0;if(!integer(g.at("playDelaySeconds"),0,3600,seconds))return false;common.playDelaySeconds=unsigned(seconds);}if(g.contains("playTargets")){if(!g["playTargets"].is_array()||g["playTargets"].size()>512)return false;for(const auto&t:g["playTargets"]){PlayTarget p;if(!t.is_object()||!integer(t.at("index"),0,30000,p.index)||!t.at("name").is_string())return false;p.name=fromUtf8(t["name"].get<std::string>());common.playTargets.push_back(p);}}if(!validGlobal(common))return false;}
    for(const auto&e:j["devices"]){SavedConfig s;if(!e.is_object()||!integer(e.at("index"),0,30000,s.index)||!seen.insert(s.index).second||!e.at("name").is_string()||!integer(e.at("functionIndex"),0,13,s.config.function)||!integer(e.at("filterIndex"),0,6,s.config.filter)||!e.at("sell").is_boolean()||!e.at("reconnect").is_boolean())return false;
        s.name=fromUtf8(e.at("name").get<std::string>());if(s.name.empty()||s.name.size()>256||!validConfig(s.config))return false;s.config.sell=e["sell"];s.config.reconnect=e["reconnect"];parsed.push_back(s);}
    out=std::move(parsed);if(global)*global=common;return true;
}catch(...){return false;}}
std::string encodeSettings(const std::vector<SavedConfig>&entries,const GlobalSettings&global){Json devices=Json::array(),targets=Json::array();for(const auto&s:entries){auto e=configJson(s.config);e["index"]=s.index;e["name"]=utf8(s.name);devices.push_back(e);}for(const auto&t:global.playTargets)targets.push_back({{"index",t.index},{"name",utf8(t.name)}});return Json({{"schema",1},{"global",{{"postConnectDelaySeconds",global.settleSeconds},{"defaults",configJson(global.defaults)},{"playDelaySeconds",global.playDelaySeconds},{"playTargets",targets}}},{"devices",devices}}).dump(2)+"\n";}
bool loadSettings(std::vector<SavedConfig>&out,std::wstring&error,GlobalSettings*global){const auto path=configPath();HANDLE h=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ,nullptr,OPEN_EXISTING,0,nullptr);if(h==INVALID_HANDLE_VALUE){if(GetLastError()==ERROR_FILE_NOT_FOUND){out.clear();if(global)*global={};return true;}error=L"Không đọc được LDMenu.json";return false;}LARGE_INTEGER size{};bool ok=GetFileSizeEx(h,&size)&&size.QuadPart>0&&size.QuadPart<=262144;std::string text(ok?size_t(size.QuadPart):0,'\0');DWORD n=0;if(ok)ok=ReadFile(h,text.data(),DWORD(text.size()),&n,nullptr)&&n==text.size();CloseHandle(h);if(!ok||!decodeSettings(text,out,global)){error=L"LDMenu.json không hợp lệ";return false;}return true;}
bool saveSettings(const std::vector<SavedConfig>&entries,std::wstring&error,const GlobalSettings&global){const auto path=configPath(),temp=path+L".tmp";const auto text=encodeSettings(entries,global);std::vector<SavedConfig> check;if(path.empty()||!validGlobal(global)||!decodeSettings(text,check)){error=L"Cấu hình không hợp lệ";return false;}
    HANDLE h=CreateFileW(temp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE){error=L"Không ghi được LDMenu.json";return false;}DWORD n=0;bool ok=WriteFile(h,text.data(),DWORD(text.size()),&n,nullptr)&&n==text.size()&&FlushFileBuffers(h);CloseHandle(h);if(ok)ok=MoveFileExW(temp.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH);if(!ok){DeleteFileW(temp.c_str());error=L"Không lưu được LDMenu.json";}return ok;
}
}
